<script setup>
import MButton from '../../../components/mds/MButton.vue'; import MEmptyState from '../../../components/mds/MEmptyState.vue'; import MSelect from '../../../components/mds/MSelect.vue';
defineProps({ title:String, currentOwnerLabel:String, currentOwnerId:[Number,String], owners:{type:Array,default:()=>[]}, ownerId:[Number,String], saving:Boolean, error:String }); const emit=defineEmits(['back','update:owner-id','submit']);
</script>
<template><section class="min-h-0 bg-[var(--mds-bg-page)] p-4"><div class="mx-auto max-w-[720px] space-y-4"><header class="flex items-start justify-between gap-4 rounded-lg bg-[var(--mds-bg)] px-5 py-4 shadow-[var(--mds-shadow-card)]"><div><p class="text-[13px] text-[var(--mds-text-secondary)]">Giải thưởng</p><h1 class="mt-1 text-[20px] font-semibold">Gán lại người phụ trách</h1></div><MButton variant="secondary" @click="emit('back')">Quay lại</MButton></header><section class="rounded-lg bg-[var(--mds-bg)] p-5 shadow-[var(--mds-shadow-card)]"><h2 class="text-[16px] font-semibold">{{ title }}</h2><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">Người phụ trách hiện tại: <strong>{{ currentOwnerLabel }}</strong></p><p class="mt-4 text-[13px] text-[var(--mds-text-secondary)]">Chỉ Admin/Super Admin được gửi thay đổi này. Máy chủ kiểm tra lại principal, bản ghi và tài khoản đang hoạt động khi xác nhận.</p><MEmptyState v-if="!owners.length" class="mt-4" title="Không có tài khoản đang hoạt động" description="Không thể gán lại owner cho tới khi máy chủ trả về tài khoản hợp lệ."/><div v-else class="mt-5 max-w-[420px]"><label class="mb-1 block text-[13px] font-medium">Người phụ trách mới</label><MSelect :model-value="ownerId" :options="owners" placeholder="Chọn người phụ trách" @update:model-value="emit('update:owner-id',$event)"/><p v-if="error" role="alert" class="mt-3 text-[13px] text-[var(--mds-danger)]">{{ error }}</p><div class="mt-6 flex justify-end gap-2"><MButton variant="secondary" @click="emit('back')">Hủy</MButton><MButton variant="primary" :loading="saving" :disabled="!ownerId||Number(ownerId)===Number(currentOwnerId)" @click="emit('submit')">Xác nhận thay đổi</MButton></div></div></section></div></section></template>
